{
  "name": "Hamilton微孔板加热振荡器",
  "name_en": "Hamilton Microplate Heater Shaker",
  "manufacturer": "Hamilton",
  "description": "用于微孔板样品加热与振荡混匀的实验室设备，可设定温度、启动或停止振荡，并可锁定板位以提高运行稳定性。常用于样品孵育、反应混合及自动化液体处理流程中的板上处理。",
  "description_en": "A laboratory device for heating and shaking microplates, with controllable temperature, start/stop shaking, and plate locking for stable operation. It is commonly used for sample incubation, reaction mixing, and on-deck plate processing in automated liquid handling workflows.",
  "tag_hints": [
    "microplate heating",
    "microplate shaking",
    "sample incubation",
    "plate locking",
    "temperature control",
    "lab automation"
  ],
  "actions": [
    {
      "action_name": "auto-send_hhs_command",
      "description": "向加热振荡器发送底层控制指令。",
      "description_en": "Send a low-level control command to the heater shaker."
    },
    {
      "action_name": "auto-supports_active_cooling",
      "description": "获取设备是否支持主动冷却。",
      "description_en": "Get whether the device supports active cooling."
    },
    {
      "action_name": "auto-serialize",
      "description": "导出设备配置或状态信息。",
      "description_en": "Export the device configuration or state information."
    },
    {
      "action_name": "auto-shake",
      "description": "以设定速度、方向和加速度振荡微孔板；必要时会先锁定板位。",
      "description_en": "Shake the microplate at the specified speed, direction, and acceleration; the plate may be locked first if needed."
    },
    {
      "action_name": "auto-stop_shaking",
      "description": "停止振荡。",
      "description_en": "Stop shaking."
    },
    {
      "action_name": "auto-get_is_shaking",
      "description": "获取设备是否正在振荡。",
      "description_en": "Get whether the device is currently shaking."
    },
    {
      "action_name": "auto-supports_locking",
      "description": "获取设备是否支持板位锁定。",
      "description_en": "Get whether the device supports plate locking."
    },
    {
      "action_name": "auto-lock_plate",
      "description": "锁定微孔板位置。",
      "description_en": "Lock the microplate in place."
    },
    {
      "action_name": "auto-unlock_plate",
      "description": "解锁微孔板位置。",
      "description_en": "Unlock the microplate."
    },
    {
      "action_name": "auto-set_temperature",
      "description": "设置加热温度。",
      "description_en": "Set the heating temperature."
    },
    {
      "action_name": "auto-get_current_temperature",
      "description": "获取当前温度。",
      "description_en": "Get the current temperature."
    },
    {
      "action_name": "auto-get_edge_temperature",
      "description": "获取边缘区域温度。",
      "description_en": "Get the edge temperature."
    },
    {
      "action_name": "auto-deactivate",
      "description": "关闭加热。",
      "description_en": "Turn off heating."
    }
  ]
}

